from svg import box, t, svg

_L = [(300, 's-box-a', 'VANGUARD: one man, no audit'), (450, 's-card', 'DOS: masters, slaves, collateral'),
      (650, 's-card', 'SASHES: ranks and the stripe path'), (850, 's-card', 'COURSES: thousands of students'),
      (1050, 's-box-j', "A FRIEND'S INVITATION")]
_inner = ''
for _i, (_w, _c, _s) in enumerate(_L):
    _y = 20 + _i * 60
    _inner += box(550 - _w // 2, _y, _w, 50, _c) + t(550, _y + 31, _s, 's-t')
FIG = svg(1100, 330, 'The NXIVM pyramid', _inner)

